# Parse dates and filter to the range Jan 18, 2023 - Nov 09, 2024 inclusive
date_format = "%b %d, %Y"
start_date = datetime.strptime("Jan 18, 2023", date_format)
end_date = datetime.strptime("Nov 09, 2024", date_format)

filtered_reviews = []
for r in reviews:
    try:
        review_date = datetime.strptime(r['date_str'], date_format)
        if start_date <= review_date <= end_date:
            filtered_reviews.append({
                'date': review_date,
                'text': r['text']
            })
    except ValueError as e:
        print(f"Date parse error: {r['date_str']}")

print(f"Reviews in date range: {len(filtered_reviews)}")
print("Sample filtered reviews:")
for r in filtered_reviews[:5]:
    print(f"  {r['date'].strftime('%Y-%m-%d')}: {r['text'][:60]}...")
```

